"""Typed Excel writer.

Writes a list of dicts into an .xlsx workbook where each column carries the
number format implied by its declared schema type.
"""

from __future__ import annotations

import datetime as _dt
from dataclasses import dataclass

from openpyxl import Workbook

from . import COLUMN_TYPES

NUMBER_FORMATS = {
    "str": "General",
    "int": "General",
    "float": "General",
    "date": "yyyy-mm-dd",
    "bool": "General",
    "percent": "0.00%",
    "currency": "$#,##0.00",
}


@dataclass(frozen=True)
class Column:
    name: str
    type: str


def normalize_schema(schema) -> list[Column]:
    """Accept a list of dicts or Column objects; validate types."""
    columns: list[Column] = []
    for i, entry in enumerate(schema):
        if isinstance(entry, Column):
            col = entry
        elif isinstance(entry, dict):
            try:
                col = Column(name=entry["name"], type=entry["type"])
            except KeyError as exc:
                raise ValueError(
                    f"Schema entry {i} missing key {exc!s}; "
                    f"expected {{'name': ..., 'type': ...}}"
                ) from exc
        else:
            raise ValueError(
                f"Schema entry {i} must be a dict or Column, got {type(entry).__name__}"
            )
        if col.type not in COLUMN_TYPES:
            raise ValueError(
                f"Unknown column type {col.type!r} for column {col.name!r}. "
                f"Expected one of: {', '.join(COLUMN_TYPES)}"
            )
        columns.append(col)
    return columns


def _coerce(col: Column, value):
    """Validate/coerce a python value before writing."""
    if value is None:
        return None
    if col.type == "str":
        return value if isinstance(value, str) else str(value)
    if col.type == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{col.name}: expected int, got {type(value).__name__}")
        return value
    if col.type in ("float", "percent", "currency"):
        # percent/currency are stored as plain numbers (fractions for percent)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{col.name}: expected number, got {type(value).__name__}")
        return float(value)
    if col.type == "date":
        if isinstance(value, _dt.datetime):
            return value.date()
        if isinstance(value, _dt.date):
            return value
        raise TypeError(f"{col.name}: expected date, got {type(value).__name__}")
    if col.type == "bool":
        if not isinstance(value, bool):
            raise TypeError(f"{col.name}: expected bool, got {type(value).__name__}")
        return value
    raise ValueError(f"Unknown column type {col.type!r}")  # pragma: no cover


def write_workbook(rows: list[dict], schema) -> Workbook:
    """Build an in-memory Workbook from rows + schema."""
    columns = normalize_schema(schema)
    wb = Workbook()
    ws = wb.active
    ws.title = "data"

    for j, col in enumerate(columns, start=1):
        cell = ws.cell(row=1, column=j, value=col.name)
        cell.font = cell.font.copy(bold=True)

    for i, row in enumerate(rows, start=2):
        for j, col in enumerate(columns, start=1):
            value = _coerce(col, row.get(col.name))
            cell = ws.cell(row=i, column=j, value=value)
            cell.number_format = NUMBER_FORMATS[col.type]

    ws.freeze_panes = "A2"
    return wb


def write_file(path: str, rows: list[dict], schema) -> str:
    """Write rows+schema to an .xlsx file at *path*. Returns the path."""
    wb = write_workbook(rows, schema)
    wb.save(path)
    return path

