"""Typed Excel reader.

Loads a workbook written by xlround.writer back into a list of dicts using
the same schema that produced it.
"""

from __future__ import annotations

import datetime as _dt

from openpyxl import load_workbook

from .writer import Column, normalize_schema


def _convert(col: Column, value):
    """Convert a raw cell value to the python type implied by the schema."""
    if value is None:
        return None
    if col.type == "str":
        if isinstance(value, (_dt.datetime, _dt.date)):
            # A cell coerced by Excel would be a datetime; the schema says text.
            raise TypeError(
                f"Column {col.name!r} is typed 'str' but cell contains "
                f"{value!r} ({type(value).__name__})"
            )
        return str(value)
    if col.type == "int":
        return int(value)
    if col.type == "float":
        return float(value)
    if col.type in ("percent", "currency"):
        # stored as a plain number (fraction for percent); read back as float
        return float(value)
    if col.type == "date":
        if isinstance(value, _dt.datetime):
            return value.date()
        if isinstance(value, _dt.date):
            return value
        raise TypeError(
            f"Column {col.name!r} is typed 'date' but cell contains {value!r}"
        )
    if col.type == "bool":
        return bool(value)
    raise ValueError(f"Unknown column type {col.type!r}")  # pragma: no cover


def _check_header(ws, columns: list[Column]) -> None:
    for j, col in enumerate(columns, start=1):
        header = ws.cell(row=1, column=j).value
        if header != col.name:
            raise ValueError(
                f"Schema/column mismatch at column {j}: workbook has header "
                f"{header!r}, schema expects {col.name!r}"
            )


def read_workbook(wb, schema) -> list[dict]:
    """Read dicts out of an openpyxl Workbook using *schema* (by position)."""
    columns = normalize_schema(schema)
    ws = wb.active if hasattr(wb, "active") else wb  # tolerate Worksheet too
    _check_header(ws, columns)

    rows: list[dict] = []
    for values in ws.iter_rows(min_row=2, max_col=len(columns), values_only=True):
        if all(v is None for v in values):
            continue  # skip fully blank trailing rows
        rows.append(
            {col.name: _convert(col, v) for col, v in zip(columns, values)}
        )
    return rows


def read_file(path: str, schema) -> list[dict]:
    """Load an .xlsx file from disk and return round-tripped dicts."""
    wb = load_workbook(path)
    return read_workbook(wb, schema)

