"""Deep comparison of original vs round-tripped row lists.

Type-aware equality:
- floats compared with absolute tolerance (default 1e-9)
- percent/currency stored as plain numbers -> compared with float tolerance
- int/bool/date/str compared exactly; None only equals None
"""

from __future__ import annotations

import datetime as _dt
import math

FLOAT_TOL = 1e-9


def _values_equal(col_type: str, a, b, tol: float) -> bool:
    if a is None or b is None:
        return a is None and b is None

    if col_type in ("float", "percent", "currency"):
        try:
            fa, fb = float(a), float(b)
        except (TypeError, ValueError):
            return False
        if math.isnan(fa) and math.isnan(fb):
            return True
        return abs(fa - fb) <= tol

    if col_type == "int":
        return not isinstance(a, bool) and not isinstance(b, bool) and int(a) == int(b)

    if col_type == "bool":
        return a is b or bool(a) == bool(b)

    if col_type == "date":
        da = a.date() if isinstance(a, _dt.datetime) else a
        db = b.date() if isinstance(b, _dt.datetime) else b
        return da == db

    # str and anything else
    return type(a) is type(b) and a == b


def compare(original: list[dict], roundtripped: list[dict], schema,
            tol: float = FLOAT_TOL) -> list[str]:
    """Return a list of human-readable mismatches (empty == identical).

    Compares row-by-row, column-by-column, using each column's declared type
    for tolerance rules.
    """
    from .writer import normalize_schema

    columns = {c.name: c.type for c in normalize_schema(schema)}
    problems: list[str] = []

    if len(original) != len(roundtripped):
        problems.append(
            f"row count mismatch: original={len(original)}, "
            f"roundtripped={len(roundtripped)}"
        )

    n_common = min(len(original), len(roundtripped))
    for i in range(n_common):
        o_row, r_row = original[i], roundtripped[i]
        for name, ctype in columns.items():
            ov, rv = o_row.get(name, "<missing>"), r_row.get(name, "<missing>")
            if not _values_equal(ctype, ov, rv, tol):
                problems.append(
                    f"row {i} column {name!r} ({ctype}): "
                    f"original={ov!r} roundtripped={rv!r}"
                )
    return problems


def assert_equal(original: list[dict], roundtripped: list[dict], schema,
                 tol: float = FLOAT_TOL) -> None:
    """Raise AssertionError with all diffs if the two row lists differ."""
    problems = compare(original, roundtripped, schema, tol=tol)
    if problems:
        preview = "\n  ".join(problems[:20])
        more = f"\n  ... and {len(problems) - 20} more" if len(problems) > 20 else ""
        raise AssertionError(
            f"{len(problems)} mismatch(es) after round-trip:\n  {preview}{more}"
        )

